mapper.select:
SELECT 
FROM geofence f JOIN organization o ON o.org_id = f.org_id
WHERE f.fence_id = #{fenceId}

mapper.sql:
FROM parking_point p JOIN organization o ON o.org_id = p.org_id LEFT JOIN vehicle_latest l ON true LEFT JOIN vehicle v ON v.vehicle_id = l.vehicle_id
AND v.org_id IN
#{orgId}

mapper.select:
SELECT 

WHERE p.point_id = #{pointId}

GROUP BY p.point_id, o.org_name

WITH visible_fences AS ( SELECT f.* FROM geofence f WHERE f.city_code = #{cityCode} AND f.status = 'ACTIVE'
), city_vehicles AS ( SELECT l.* FROM vehicle v JOIN vehicle_latest l ON l.vehicle_id = v.vehicle_id WHERE v.operation_city_code = #{cityCode}
), violations AS ( SELECT cv.vehicle_id, 'OUTSIDE_OPERATION' AS violation_type, NULL::varchar AS facility_id, NULL::varchar AS facility_name, cv.longitude, cv.latitude, cv.battery_percent, cv.reported_at FROM city_vehicles cv WHERE EXISTS (SELECT 1 FROM visible_fences f WHERE f.fence_type = 'OPERATION') AND NOT EXISTS ( SELECT 1 FROM visible_fences f WHERE f.fence_type = 'OPERATION' AND ST_Covers(f.boundary, cv.position) ) UNION ALL SELECT cv.vehicle_id, 'IN_NO_PARK', f.fence_id, f.fence_name, cv.longitude, cv.latitude, cv.battery_percent, cv.reported_at FROM city_vehicles cv JOIN visible_fences f ON f.fence_type = 'NO_PARK' AND ST_Covers(f.boundary, cv.position) WHERE cv.ride_status = 'IDLE' UNION ALL SELECT cv.vehicle_id, 'RIDING_IN_NO_RIDE', f.fence_id, f.fence_name, cv.longitude, cv.latitude, cv.battery_percent, cv.reported_at FROM city_vehicles cv JOIN visible_fences f ON f.fence_type = 'NO_RIDE' AND ST_Covers(f.boundary, cv.position) WHERE cv.ride_status = 'RIDING' ) SELECT * FROM violations ORDER BY reported_at DESC LIMIT 500
